<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS bons_commande (id INT AUTO_INCREMENT PRIMARY KEY,devis_id INT NOT NULL,numero_bc VARCHAR(120) NOT NULL,reference_client VARCHAR(190),date_commande DATE NOT NULL,date_livraison_prevue DATE NULL,fichier_bc VARCHAR(255),fichier_original VARCHAR(255),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_order_quote(devis_id),UNIQUE KEY uniq_order_number(numero_bc)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
